"use strict";(globalThis.webpackChunkgrc||=[]).push([[26688],{62288(e){e.exports=JSON.parse('[{"citeKey":"chittyvenkata2026pagedeviction","slug":"chitty-venkata-2026-pagedeviction-3f8a","title":"PagedEviction: Structured Block-wise KV Cache Pruning for Efficient Large Language Model Inference","authors":["K. Chitty-Venkata","J. Ye","S. Raskar","A. Kougkas","X.-H. Sun","M. Emani","V. Vishwanath","B. Nicolae"],"venue":"Findings of the Association for Computational Linguistics (EACL 2026)","type":"Conference","entryType":"inproceedings","date":"March, 2026","year":2026,"era":"iit","month":3,"doi":"10.18653/v1/2026.findings-eacl.168","abstract":"KV caching significantly improves the efficiency of Large Language Model (LLM) inference by storing attention states from previously processed tokens, enabling faster generation of subsequent tokens. However, as sequence length increases, the KV cache quickly becomes a major memory bottleneck. To address this, we propose PagedEviction, a novel fine-grained, structured KV cache pruning strategy that enhances the memory efficiency of vLLM\'s PagedAttention. Unlike existing approaches that rely on attention-based token importance or evict tokens across different vLLM pages, PagedEviction introduces an efficient block-wise eviction algorithm tailored for paged memory layouts. Our method integrates seamlessly with PagedAttention without requiring any modifications to its CUDA attention kernels. We evaluate PagedEviction across Llama-3.1-8B-Instruct, Llama-3.2-1B-Instruct, and Llama-3.2-3B-Instruct models on the LongBench benchmark suite, demonstrating improved memory usage with better accuracy than baselines on long context tasks.","hasAbstract":true,"lede":"To address this, we propose PagedEviction, a novel fine-grained, structured KV cache pruning strategy that enhances the memory efficiency of vLLM\'s PagedAttention.","pages":"3207\u20133218","links":{"pdf":"https://aclanthology.org/2026.findings-eacl.168.pdf"},"tags":["KV Cache","Compression","LLM Inference Serving"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2022stimulus","slug":"devarajan-2022-stimulus-4b4c","title":"Stimulus: Accelerate Data Management for Scientific AI applications in HPC","authors":["H. Devarajan","A. Kougkas","H. Zheng","V. Vishwanath","X.-H. Sun"],"venue":"The 22nd IEEE/ACM International Symposium on Cluster, Cloud and Internet Computing (CCGRID\'22), May 16-19, 2022","type":"Conference","entryType":"inproceedings","date":"May, 2022","year":2022,"era":"iit","month":5,"doi":"10.1109/ccgrid54584.2022.00020","abstract":"Modern scientific workflows couple simulations with AI-powered analytics by frequently exchanging data to accelerate time-to-science to reduce the complexity of the simulation planes. However, this data exchange is limited in performance and portability due to a lack of support for scientific data formats in AI frameworks. We need a cohesive mechanism to effectively integrate at scale complex scientific data formats such as HDF5, PnetCDF, ADIOS2, GNCF, and Silo into popular AI frameworks such as TensorFlow, PyTorch, and Caffe. To this end, we designed Stimulus, a data management library for ingesting scientific data effectively into the popular AI frameworks. We utilize the StimOps functions along with StimPack abstraction to enable the integration of scientific data formats with any AI framework. The evaluations show that Stimulus outperforms several large-scale applications with different use-cases such as Cosmic Tagger (con- suming HDF5 dataset in PyTorch), Distributed FFN (consuming HDF5 dataset in TensorFlow), and CosmoFlow (converting HDF5 into TFRecord and then consuming that in TensorFlow) by 5.3x, 2.9x, and 1.9\xd7 respectively with ideal I/O scalability up to 768 GPUs on the Summit supercomputer. Through Stimulus, we can portably extend existing popular AI frameworks to cohesively support any complex scientific data format and efficiently scale the applications on large-scale supercomputers.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2022/devarajan-2022-stimulus-4b4c.pdf"},"tags":["HDF5","TensorFlow","Decoupled I/O","I/O Acceleration","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2021dlio","slug":"devarajan-2021-dlio-0272","title":"DLIO: A Data-Centric Benchmark for Scientific Deep Learning Applications","authors":["H. Devarajan","H. Zheng","A. Kougkas","X.-H. Sun","V. Vishwanath"],"venue":"The 2021 IEEE/ACM International Symposium in Cluster, Cloud, and Internet Computing (CCGrid\'21), May 17 - 20, 2021 Best paper award","type":"Conference","entryType":"inproceedings","date":"May, 2021","year":2021,"era":"iit","month":5,"doi":"10.1109/ccgrid51090.2021.00018","abstract":"Deep learning has been shown as a successful method for various tasks, and its popularity results in numerous open-source deep learning software tools. Deep learning has been applied to a broad spectrum of scientific domains such as cosmology, particle physics, computer vision, fusion, and astrophysics. Scientists have performed a great deal of work to optimize the computational performance of deep learning frameworks. However, the same cannot be said for I/O perfor- mance. As deep learning algorithms rely on big-data volume and variety to effectively train neural networks accurately, I/O is a significant bottleneck on large-scale distributed deep learning training. This study aims to provide a detailed investigation of the I/O behavior of various scientific deep learning workloads running on the Theta supercomputer at Argonne Leadership Computing Facility. In this paper, we present DLIO, a novel representative benchmark suite built based on the I/O profiling of the selected workloads. DLIO can be utilized to accurately emulate the I/O behavior of modern scientific deep learning applications. Using DLIO, application developers and system software solution architects can identify potential I/O bottlenecks in their applications and guide optimizations to boost the I/O performance leading to lower training times by up to 6.7x.","hasAbstract":true,"lede":"We present DLIO, a novel representative benchmark suite built based on the I/O profiling of the selected workloads.","links":{"pdf":"https://grc.iit.edu/papers/2021/devarajan-2021-dlio-0272.pdf","video":"https://youtu.be/_rRhQBaHVs8"},"tags":["Deep Learning","Scientific Applications","Representative","Benchmark","Data-Intensive","I/O","Characterization","TensorFlow","Data Pipeline","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"grcAwards":"Best Paper Award (First Prize)","status":"published","visibility":"public"},{"citeKey":"devarajan2020understandingio","slug":"devarajan-2020-understanding-io-755d","title":"Understanding I/O behavior of Scientific Deep Learning Applications in HPC systems","authors":["H. Devarajan","H. Zheng","X.-H. Sun","V. Vishwanath"],"venue":"The International Conference for High Performance Computing, Networking, Storage and Analysis (SC\'20)","type":"Poster","entryType":"misc","date":"November, 2020","year":2020,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2020/devarajan-2020-understanding-io-755d.pdf","poster":"https://grc.iit.edu/papers/2020/devarajan-2020-understanding-io-755d-poster.pdf"},"_projectIds":[],"_funding":[{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"}]')}}]);